local uihelper = require(script.Parent.Parent.UIHelper)

local module = {}
module.__index = module

function module.new(viewProvider, contentProvider, getTransition)
    local self = {}
    
    setmetatable(self, module)
    self._stack = {}
    self._viewProvider = viewProvider
    self._contentProvider = contentProvider
    self._getTransition = getTransition
    
    return self
end

function module:GetContent()
    return self._contentProvider()
end

function module:StackPush(panel)
    local idx = table.find(self._stack, panel)
    if idx == #self._stack then
        return
    end
    if idx then
        table.remove(self._stack, idx)
    end
    table.insert(self._stack, panel)
    return true
end

function module:StackPop(panel)
    local idx = table.find(self._stack, panel)
    if not idx then
        return
    end
    table.remove(self._stack, idx)
    return true
end

function module:Push(panel, ...)
    local suc = self:StackPush(panel)
    if not suc then
        return
    end
    for i, v in pairs(self._stack) do
        if v == panel then
            break
        end
        if v._showing then
            v:Hide()
        end
    end
    panel:Show(self, ...)
end

function module:Pop(panel, ...)
    local suc = self:StackPop(panel)
    if not suc then
        return
    end
    if panel._showing then
        panel:Hide(...)
    end
    local top = self._stack[#self._stack]
    if top then
        top:Show(self, ...)
    end
end

function module:Show(panel, ...)
    local top = self._stack[#self._stack]
    if top and top._showing then
        top:Hide()
    end
    table.clear(self._stack)
    table.insert(self._stack, panel)
    panel:Show(self, ...)
end

function module:Hide(panel, ...)
    local idx = table.find(self._stack, panel)
    if not idx then
        return
    end
    table.remove(self._stack, idx)
    if panel._showing then
        panel:Hide(...)
    end
end

function module:Clean(...)
    for i, v in pairs(self._stack) do
        if v._showing then
            v:Hide(...)
        end
    end
    table.clear(self._stack)
end

return module